code.text:
# UC-1 を、宣言（JSON）の欄の名前のまま YAML の記法で示す。ID は位置から機械的に導く
id: UC-1
name: 注文を確定する
scope: {context: BC-注文受付, visibility: ブラックボックス}
level: ユーザー目的
primary_actor: {role: 顧客, on_behalf_of: null}
supporting_actors:
  - {id: SA-1, name: 決済代行}
stakeholders:
  - {id: SH-1, who: 顧客, interest: 注文した商品を受け取り、確定した合計額だけを支払う}
  - {id: SH-2, who: 店舗, interest: 支払いの承認を得た注文だけを確定し、在庫を超えて販売しない}
  - {id: SH-3, who: 経理, interest: 確定と請求の記録を、後から突き合わせられる}
contributes_to: [AC-2]            # ドメインの宣言の達成の基準
writes_aggregates: [AG-在庫, AG-注文]
preconditions:
  - {id: PRE-1, text: 顧客が識別されている, established_by: UC-8}
  - {id: PRE-2, text: カートに1品以上の商品が入っている, established_by: UC-2}
trigger: {kind: 主アクターが直接始める, event: 顧客が注文の確定を依頼する, is_step_1: true}
minimal_guarantees:
  - {id: MG-1, protects: [SH-2], text: 決済代行の承認を受けていない注文は、確定しない}
  - {id: MG-2, protects: [SH-1, SH-2], text: 顧客への請求額は確定した注文の合計額と等しく、確定しなかった注文には請求の承認も在庫の引当ても残らない}
  - {id: MG-3, protects: [SH-2, SH-3], text: 確定の試みが、どの手順まで進んだかが注文の経過として残る}
success_guarantees:               # 最低保証に足す形。SG-1 がタイトルの目的
  - {id: SG-1, satisfies: [SH-1], text: 注文が確定し、確定した合計額だけが顧客に請求される}
  - {id: SG-2, satisfies: [SH-1, SH-2], text: 注文の商品と数量の在庫が、その注文に引き当てられている}
  - {id: SG-3, satisfies: [SH-3], text: 承認番号と確定した合計額が注文に記録される}
main_success_scenario:            # 3〜9手順。1手順は「主語・種類・文」
  - {no: 1, actor: 顧客, kind: 相互作用, to: システム, data: [受け取り方法, 支払い手段],
     text: 顧客は、受け取り方法と支払い手段を添えて、注文の確定をシステムに依頼する}
  - {no: 2, actor: システム, kind: 妥当性確認, serves: [SH-1, SH-2],
     text: システムは、カートの商品の価格が提示した額から変わっておらず、在庫が注文の数量に足りていることを確認する}
  - {no: 3, actor: システム, kind: 内部の状態変化, aggregate: AG-在庫, saga: SAGA-1, serves: [SH-2],
     text: システムは、注文の商品と数量の在庫を引き当てる}
  - {no: 4, actor: システム, kind: 相互作用, to: 決済代行, data: [請求額, 支払い手段], saga: SAGA-2, serves: [SH-2],
     text: システムは、決済代行に請求額の承認を依頼し、承認番号を受け取る}
  - {no: 5, actor: システム, kind: 内部の状態変化, aggregate: AG-注文, saga: SAGA-3, serves: [SH-1, SH-3],
     text: システムは、注文を確定し、承認番号・確定した合計額・確定の経過を注文に記録する}
  - {no: 6, actor: システム, kind: 相互作用, to: 顧客, data: [注文番号, 受け取りの予定],
     text: システムは、顧客に注文番号と受け取りの予定を知らせる}
extensions:                       # 結び付く手順・条件の種類・条件・処理・終わり方
  - label: 2a
    anchor: {step: 2}
    condition_kind: 確認の失敗
    condition: 提示した額から価格が変わった商品があった：
    steps:
      - {no: 2a1, actor: システム, kind: 相互作用, to: 顧客, data: [変わった価格], text: システムは、顧客に変わった価格を示す}
      - {no: 2a2, actor: 顧客, kind: 相互作用, to: システム, text: 顧客は、変わった価格を受け入れる}
    ending: {kind: 同じ手順へ戻る, to: 2}
    extensions:
      - label: 2a2a
        anchor: {step: 2a2}
        condition_kind: 主アクターの取りやめ
        condition: 顧客が変わった価格を受け入れなかった：
        steps:
          - {no: 2a2a1, actor: システム, kind: 内部の状態変化, aggregate: AG-注文, serves: [SH-3], text: システムは、確定しなかった理由と進んだ手順を注文の経過に記録する}
        ending: {kind: 失敗する}
  - label: 2b
    anchor: {step: 2}
    condition_kind: 確認の失敗
    condition: 在庫が注文の数量に足りない商品があった：
    steps:
      - {no: 2b1, actor: システム, kind: 内部の状態変化, aggregate: AG-注文, serves: [SH-3], text: システムは、確定しなかった理由と進んだ手順を注文の経過に記録する}
      - {no: 2b2, actor: システム, kind: 相互作用, to: 顧客, data: [足りない商品, 引き当てられる数量], text: システムは、顧客に足りない商品と引き当てられる数量を知らせる}
    ending: {kind: 失敗する}
  - label: 4a
    anchor: {step: 4}
    condition_kind: 支援アクターの応答無しまたは誤り
    condition: 決済代行から、時間内に承認の応答が無かった：
    steps:
      - {no: 4a1, actor: システム, kind: 相互作用, to: 決済代行, compensates: SAGA-2, text: システムは、決済代行に承認の取消を依頼する}
      - {no: 4a2, actor: システム, kind: 内部の状態変化, aggregate: AG-在庫, compensates: SAGA-1, text: システムは、引き当てた在庫を解放する}
      - {no: 4a3, actor: システム, kind: 内部の状態変化, aggregate: AG-注文, serves: [SH-3], text: システムは、確定しなかった理由と進んだ手順を注文の経過に記録する}
      - {no: 4a4, actor: システム, kind: 相互作用, to: 顧客, text: システムは、顧客に注文を確定できなかったことを知らせる}
    ending: {kind: 失敗する}
variations:                       # 「どのように」だけが変わるもの。条件と処理を書かない。技術の語を書かない
  - {step: 4, varies: 支払い手段, values: [クレジットカード, デビットカード, 電子マネー]}
saga:                             # writes_aggregates が2件以上のときだけ置く（推測：支援アクターも手順に含める）
  - {id: SAGA-1, step: 3, target: AG-在庫, postcondition: 注文の商品と数量の在庫が引き当てられている, compensation: 引き当てた在庫を解放する}
  - {id: SAGA-2, step: 4, target: SA-1, postcondition: 請求額の承認番号がある, compensation: 決済代行に承認の取消を依頼する}
  - {id: SAGA-3, step: 5, target: AG-注文, postcondition: 注文が確定済みで、承認番号と合計額を持つ, compensation: なし（最後の手順）}
open_issues:
  - 決済代行が時間内に応答せず、のちに承認を返した場合の扱いは未決定

# 導かれる試験（シナリオの単位。ID は UC の ID ＋ 拡張のラベル。主成功シナリオは M）
# UC-1.M     準備 PRE-1・PRE-2 ／ SA-1 の偽物は承認を返す ／ SG-1〜3 と MG-1〜3 を検証
# UC-1.2a    手順2で価格差を準備 → 2a1・2a2 → 手順2へ戻る → 3〜6 ／ SG-1〜3 を検証
# UC-1.2a2a  2a2 で取りやめ ／ MG-1〜3 を検証（SG は成り立たないことも検証）
# UC-1.2b    手順2で在庫不足を準備 ／ MG-1〜3 を検証
# UC-1.4a    SA-1 の偽物が応答しない ／ MG-1〜3 を検証
# サーガ     SAGA-1〜3 の事後条件 ／ 4a で SAGA-2・SAGA-1 の補償が逆順に実行されることを検証
